// يتحقق من توقيع Zinor (HMAC-SHA256 على "timestamp.body") — يلزم NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const item = $input.first().json;
const h = item.headers || {};
const body = JSON.stringify(item.body);
const ts = Number(h['x-zinor-timestamp']);
if (!ts || Math.abs(Date.now() / 1000 - ts) > 300) throw new Error('Zinor: timestamp قديم ولا ناقص');
const expected = crypto.createHmac('sha256', $env.CALLS_WEBHOOK_SECRET).update(`${ts}.${body}`).digest('hex');
if (h['x-zinor-signature'] !== expected) throw new Error('Zinor: توقيع غير صالح');
const b = item.body;
const auth = 'Basic ' + Buffer.from(`${$env.TWILIO_ACCOUNT_SID}:${$env.TWILIO_AUTH_TOKEN}`).toString('base64');
const statusUrl = `${$env.N8N_PUBLIC_URL}/webhook/zinor-call-status?call_id=${encodeURIComponent(b.call_id)}`;
return [{ json: { to: b.to, turn_url: b.turn_url, status_url: statusUrl, auth, machine: b.machine_detection ? 'Enable' : '' } }];

// يتحقق من توقيع Twilio (X-Twilio-Signature) ثم يبني طلب موقّع لـ Zinor
const crypto = require('crypto');
const item = $input.first().json;
const h = item.headers || {};
const q = item.query || {};
const params = item.body || {};
const qs = new URLSearchParams(q).toString();
const url = `${$env.N8N_PUBLIC_URL}/webhook/zinor-turn${qs ? '?' + qs : ''}`;
const data = url + Object.keys(params).sort().map((k) => k + params[k]).join('');
const expected = crypto.createHmac('sha1', $env.TWILIO_AUTH_TOKEN).update(Buffer.from(data, 'utf-8')).digest('base64');
if (h['x-twilio-signature'] !== expected) throw new Error('Twilio: توقيع غير صالح (تأكد من N8N_PUBLIC_URL)');
const payload = {
  call_id: q.call_id ? Number(q.call_id) : null,
  provider_call_id: params.CallSid,
  from: params.From, to: params.To,
  direction: q.direction === 'inbound' || params.Direction === 'inbound' ? 'inbound' : 'outbound',
  speech: params.SpeechResult || '', confidence: params.Confidence || null,
  answered_by: params.AnsweredBy || null, silence: q.silence === '1' && !params.SpeechResult,
};
const body = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000);
const sig = crypto.createHmac('sha256', $env.CALLS_WEBHOOK_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts: String(ts), sig } }];

